// One-hot to binary function, used to convert the one-hot encoded next state
// (Y_next) to the binary register increment (increment).
function [2:0] oh2bin;
    input [2:0] one_hot;
    begin
        case (one_hot)
            3'b001: oh2bin = 3'b000;
            3'b010: oh2bin = 3'b001;
            3'b100: oh2bin = 3'b010;
            3'b000: oh2bin = 3'b011;
            default: oh2bin = 3'b111;
        endcase
    end
endfunction

// SynchronousFSM_combined: Functional form of the combinational FSM,
// equivalent to the reference theoretical model. Same transition and
// next-state function as in the textbook.
module SynchronousFSM_combined (
    input  clk,
    input  x,
    input  [2:0] y,
    output reg Y0,
    output reg z
);
    reg [2:0] Y, Y_next;
    always @(*) begin
        case ({y, x})
            6'b000000: begin Y_next = 3'b000; z = 1'b0; end
            6'b000001: begin Y_next = 3'b001; z = 1'b0; end
            6'b000010: begin Y_next = 3'b010; z = 1'b0; end
            6'b000011: begin Y_next = 3'b001; z = 1'b1; end
            6'b000100: begin Y_next = 3'b011; z = 1'b1; end
            default: begin Y_next = 3'b111; z = 1'bx; end
        endcase
        Y = oh2bin(Y_next);
        Y0 = (Y == 3'b000);
    end
    always @(posedge clk) begin
        Y <= Y_next;
    end
endmodule

// One-hot state encoding: state s corresponds to the binary number s, for s in
// 0..2**n - 1.
module TopModule(input  clk, input  x, input  [2:0] y, output reg Y0, output reg z);
  reg [2:0] state, next_state;
  always @(*) begin
    case ({x, state, y}) // FULLY CONNECTED CASE STATEMENT
      6'b000000: next_state = 3'b000;
      6'b000001: next_state = 3'b001;
      6'b000010: next_state = 3'b010;
      6'b000011: next_state = 3'b001;
      6'b000100: next_state = 3'b100;
      6'b010000: next_state = 3'b000;
      6'b010001: next_state = 3'b001;
      6'b010010: next_state = 3'b001;
      6'b010011: next_state = 3'b010;
      6'b010100: next_state = 3'b011;
      default: next_state = 3'bxxx;
    endcase
    Z0 = (state == next_state);
