// One-hot to binary function
function [2:0] oh_to_bin;
    input [2:0] one_hot;
    begin
        case (one_hot)
            3'b001: oh_to_bin = 0;
            3'b010: oh_to_bin = 1;
            3'b100: oh_to_bin = 2;
            default: oh_to_bin = 3;
        endcase
    end
endfunction

// Next state and output function
function [2:0] next_state_and_output;
    input [2:0] state;
    input x;
    input [2:0] y;
    reg [2:0] next_state;
    reg z;
    begin
        case (state)
            0: begin next_state = x ? 1 : 0; z = 0; end
            1: begin next_state = x ? 2 : 0; z = 0; end
            2: begin next_state = x ? 2 : 1; z = 0; end
            3: begin next_state = x ? 0 : 2; z = 1; end
            4: begin next_state = x ? 5 : 3; z = 0; end
            5: begin next_state = x ? 5 : 4; z = 1; end
            default: begin next_state = 0; z = 0; end
        endcase
        next_state_and_output = {next_state, z};
    end
endfunction

