    // multiplexer with a nested multiplexer (the second one
    // selecting the output Y0).
    // The first selects the next state, the second selects the
    // output.
    {3'b000, 1'b0}: begin nextstate = 3'b000; Y0_next = 1'b0; z_next = 1'b0; end
    {3'b000, 1'b1}: begin nextstate = 3'b001; Y0_next = 1'b0; z_next = 1'b0; end
    {3'b001, 1'b0}: begin nextstate = 3'b001; Y0_next = 1'b0; z_next = 1'b0; end
    {3'b001, 1'b1}: begin nextstate = 3'b100; Y0_next = 1'b0; z_next = 1'b0; end
    {3'b010, 1'b0}: begin nextstate = 3'b010; Y0_next = 1'b0; z_next = 1'b0; end
    {3'b010, 1'b1}: begin nextstate = 3'b001; Y0_next = 1'b0; z_next = 1'b0; end
    {3'b011, 1'b0}: begin nextstate = 3'b001; Y0_next = 1'b1; z_next = 1'b1; end
