// One-hot state encoding: state s is encoded as a 3-bit vector such that
// s[2] is the highest bit, s[1] is the second bit, and s[0] is the lowest
// bit. The state s is one-hot encoded, meaning it's all 0s except for the
// bit corresponding to the state (starting from 0).
// Functional form of the next state logic: a big lookup table that goes
// from the 3-bit current state and x to the 3-bit next state.
module TopModule(
    input  clk,
    input  x,
    input  [2:0] y,
    output reg Y0,
    output reg z
);
    reg [2:0] s, sn;
    always @(*) begin
        case ({s, x})
            // ONEHOT("00000"), ONEHOT("00100") -> Y0=0, z=0
            6'b000000: sn = 3'b000;
            6'b001000: sn = 3'b000;
            // ONEHOT("00001"), ONEHOT("00101") -> Y0=0, z=0
            6'b000010: sn = 3'b001;
            6'b001010: sn = 3'b001;
            // ONEHOT("00010"), ONEHOT("00100") -> Y0=0, z=0
            6'b000100: sn = 3'b010;
            6'b001000: sn = 3'b010;
            // ONEHOT("00110"), ONEHOT("00101") -> Y0=1, z=1
            6'b001100: sn = 3'b001;
            6'b001010: sn = 3'b001;
            // ONEHOT("00111"), ONEHOT("01011") -> Y0=1, z=1
            6'b001110: sn = 3'b011;
            6'b010110: sn = 3'b011;
            // ONEHOT("01000"), ONEHOT("01010") -> Y0=1, z=1
            6'b010000: sn = 3'b011;
            6'b010100: sn = 3'b011;
            // ONEHOT("01001"), ONEHOT("01011") -> Y0=1, z=1
            6'b010010: sn = 3'b011;
            6'b010110: sn = 3'b011;
            // ONEHOT("01100"), ONEHOT("01010") -> Y0=1, z=1
            6'b011000: sn = 3'b011;
            6'b010100: sn = 3'b011;
            // ONEHOT("01101"), ONEHOT("01011") -> Y0=1, z=1
            6'b011010: sn = 3'b011;
            6'b010110: sn = 3'b011;
            default: sn = 3'bx;
        endcase
    end
    always @(posedge clk) begin
        s <= sn;
        Y0 <= s[0];
        z <= s[2];
    end
endmodule
